add(nr=201, id="10494680563978", orig_titel="Massagerulle Tunturi Kork Massagerulle",
 fakta='''Massagerulle Tunturi Kork Massagerulle. Tunturi massagerulle är tillverkad av kork och förbättrar flexibiliteten i muskler och bindväv samt främjar återhämtning utan behov av en massör. Det är en effektiv metod för att behandla hud, muskler och spända punkter som en uppvärmning före träning eller avslappning efter träning. Den höga korkdensiteten säkerställer att rullen inte tappar formen, även vid intensiv användning. Rullen kan även användas för funktionella övningar samt balans- och rörlighetsövningar. Fördelar: Tillverkad av 100% naturligt och biologiskt nedbrytbart material. Förbättrar flexibiliteten och främjar återhämtning av muskler och bindväv. Stöder naturlig och hälsosam rörelse. Lämplig för balansövningar. Den 100 % ekologiska massagerullen är tillverkad av 100 % naturlig och återvinningsbar kork. Kork är ett hållbart och miljövänligt material. Den är bekväm mot huden och kan användas intensivt utan att tappa kvalitet. "Mår bättre varje dag" är Tunturis motto. Våra rötter går tillbaka till Finland, där två bröder grundade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och stark kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Tekniska specifikationer i översikt: Mått. Vikt: 680 gr Material och färg: kork. Märke Tunturi, typ Massage, variant Default Title, SKU 14TUSYO061''',
 titel="Träningsrulle Tunturi Kork, 680 g",
 seo_title="Träningsrulle Tunturi Kork, 680 g",
 meta="Tunturi Kork är en träningsrulle i kork på 680 g. Kan användas för uppvärmning före träning samt för funktionella övningar, balans- och rörlighetsövningar.",
 intro="Tunturi Kork är en träningsrulle i kork som väger 680 g. Den kan användas för uppvärmning före träning och för funktionella övningar samt balans- och rörlighetsövningar.",
 passar=["Dig som vill ha en rulle i kork för uppvärmning före träning","Dig som vill göra balansövningar och rörlighetsövningar","Dig som vill göra funktionella övningar"],
 spec=["Material: kork","Vikt: 680 g"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Utelämnat: all text om massage, behandling av hud/muskler, flexibilitet och återhämtning (effektlöften), 'effektiv', 'hälsosam', miljö- och nedbrytbarhetspåståenden ('100 % naturligt', 'biologiskt nedbrytbart', 'ekologisk', 'miljövänlig'), hållbarhetslöften och Tunturis märkestext (historia, Finland, Nederländerna). Orden massage/massagerulle används inte (hälsoord i standarden), så typen är satt till 'Träningsrulle'.",
 att_bekrafta=["Originaltiteln och produkttypen säger 'Massagerulle'; typen i titeln har ändrats till 'Träningsrulle' för att undvika massage-ordet. Bekräfta att det är rätt namn.","Mått saknas (källan har en tom rad 'Mått.').","Källan säger både att materialet är '100 % naturligt och biologiskt nedbrytbart' och '100 % ekologiskt/återvinningsbart'. Miljöpåståendena kräver belägg och är utelämnade.","Rullens form och storlek (längd, diameter) framgår inte."])

add(nr=202, id="10588447342858", orig_titel="Träningsboll TUNTURI Gym Ball 65cm, Anti-Burst, Rose Gold",
 fakta='''Träningsboll TUNTURI Gym Ball 65cm, Anti-Burst, Rose Gold. Om du letar efter en träningsboll som inte bara tar din träning till nästa nivå, utan också är lämplig för yoga, stretching och kanske till och med för att sitta vid ett skrivbord, är Tunturi Gymball ett utmärkt val! Tunturi Gymball är designad för att klara vikter upp till 220 kg, vilket säkerställer hållbarhet och stabilitet i varje rörelse. Välj rätt storlek på bollen för din längd: 55 cm - lämplig för längder mellan 155-165 cm. 65 cm - lämplig för längd 166-178 cm. 75 cm - lämplig för längder 179-190 cm. 90 cm - lämplig för längd > 190 cm. Tillverkare . Detaljer: Diameter: 65 cm. Produktvikt: 1,1 kg. Bärförmåga: 220 kg. Produkten finns på Tunturis webbplats. Märke Tunturi, typ Konditionsträning & Fitness, variant Default Title, SKU 14TUSFU341, status i butiken: utkast''',
 titel="Träningsboll Tunturi Gymball 65 cm, anti-burst, roséguld",
 seo_title="Träningsboll Tunturi Gymball 65 cm",
 meta="Tunturi Gymball är en träningsboll med diameter 65 cm och bärförmåga 220 kg. Lämplig för yoga och stretching. Produktvikt 1,1 kg, färg roséguld.",
 intro="Tunturi Gymball 65 cm är en träningsboll med diameter 65 cm och en bärförmåga på 220 kg. Den är lämplig för yoga och stretching.",
 passar=["Dig som är 166–178 cm lång enligt tillverkarens storleksguide","Dig som vill träna yoga och stretching med en boll","Dig som vill kunna sitta på bollen vid ett skrivbord"],
 spec=["Diameter: 65 cm","Produktvikt: 1,1 kg","Bärförmåga: 220 kg","Färg: roséguld (enligt titeln)"],
 faq=[("Vilken storlek ska jag välja?","Enligt tillverkarens storleksguide är 65 cm lämplig för längd 166–178 cm.")], marke=None,
 motivering="Fakta ur källan. Utelämnat: 'nästa nivå', 'utmärkt val', 'hållbarhet och stabilitet i varje rörelse' (säljfraser) samt länken till Tunturis webbplats. Anti-Burst och roséguld tas från originaltiteln.",
 att_bekrafta=["Produkten har status utkast (DRAFT) i butiken.","Anti-Burst förklaras inte i beskrivningen, bara i titeln.","Beskrivningen nämner inte om pump ingår (länkens adress antyder det, men det står inte som text).","Färgen roséguld står bara i titeln, inte i detaljerna.","Raden 'Tillverkare .' är tom."])

