add(nr=204, id="10470998147338", orig_titel="Träningsboll TUNTURI Gymball 75cm Anti Burst, lila",
 fakta='''Träningsboll TUNTURI Gymball 75cm Anti Burst, lila. Fördelar med Tunturi Gymbal: Skottsäker. Hållbar - Tålig mot stötar och vibrationer. Oförstörbar eftersom den tål belastningar upp till 350 kg. Uppblåsbar och därmed lätt att förvara. Med den medföljande pumpen kan du blåsa upp den var du vill. Tekniska data översikt: Vikt: 1198 gr. Färg: Svart. Material: vinyl. Ø: 75 cm. 11.Vin Vinyl: PVC: PVC: Vinyl: PVC: PVC: Vinyl: PVC: PVC: PVC: Vinyl: Vinyl: Vinyl: PVC: PVC: PVC: PVC: PVC: Vinyl: Vinyl. Notera: när du använder bollen för första gången, fyll den med maximal mängd luft. Bollen kan sträcka sig till rätt storlek inom 1 eller 2 dagar. Vilken storlek behöver du? Kroppslängd upp till 155 cm = Ø 45 cm. 155 cm - 165 cm = Ø 55 cm. 166 cm - 178 cm = Ø 65 cm. 179 cm - 190 cm = Ø 75 cm. 190 cm eller längre = Ø 90 cm. "Mår bättre varje dag" - det är Tunturis motto. Våra rötter finns i Finland, där två bröder grundade en cykelbutik 1922. Nu, mer än 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Det är ett sortiment som ständigt utökas och utvecklas, med högkvalitativa produkter och bra garantier. Märke Tunturi, typ Träningsbollar, variant Default Title, SKU 14TUSFU338''',
 titel="Träningsboll Tunturi Gymball 75 cm, anti-burst",
 seo_title="Träningsboll Tunturi Gymball 75 cm",
 meta="Tunturi Gymball är en uppblåsbar träningsboll i vinyl med diameter 75 cm och vikt 1198 g. Pump medföljer. Anti-burst. Passar längd 179–190 cm.",
 intro="Tunturi Gymball 75 cm är en uppblåsbar träningsboll i vinyl med diameter 75 cm. En pump medföljer.",
 passar=["Dig som är 179–190 cm lång enligt tillverkarens storleksguide","Dig som vill ha en uppblåsbar boll som är lätt att förvara","Dig som vill kunna blåsa upp bollen var du vill med den medföljande pumpen"],
 spec=["Diameter: 75 cm","Material: vinyl","Vikt: 1198 g","Uppblåsbar, pump medföljer","Första användningen: fyll med maximal mängd luft; bollen kan sträcka sig till rätt storlek inom 1 eller 2 dagar"],
 faq=[("Vilken storlek ska jag välja?","Enligt tillverkarens storleksguide är 75 cm lämplig för kroppslängd 179–190 cm."),("Hur gör jag första gången?","Fyll bollen med maximal mängd luft. Den kan sträcka sig till rätt storlek inom 1 eller 2 dagar.")], marke=None,
 motivering="Fakta ur källan. Utelämnat: 'Skottsäker', 'Oförstörbar', belastningsuppgiften 350 kg (orimlig och avviker från andra Gymball-produkter), 'tålig mot stötar och vibrationer', färgen (motsägelse), den trasiga materialraden och Tunturis märkestext.",
 att_bekrafta=["Färgen: titeln säger lila men detaljerna säger 'Färg: Svart'. Färg utelämnad ur titeln.","'Skottsäker' och 'Oförstörbar' är orimliga påståenden, och 350 kg avviker från 220 kg hos andra Gymball-produkter. Verklig bärförmåga behövs.","Raden '11.Vin Vinyl: PVC: …' är trasig maskinöversättning och är inte medtagen.","Anti-burst står bara i titeln."])

add(nr=205, id="10472284258570", orig_titel="Pilatesring Tunturi Pilates Ring, Svart",
 fakta='''Pilatesring Tunturi Pilates Ring, Svart. En Pilatesring som ger motstånd under övningarna. Den låter dig träna djupa muskler utan behov av specialutrustning. Du kommer att utveckla muskelstyrka och uthållighet samtidigt som du tränar din balans genom att applicera samma tryck på båda sidor av ringen, vilket gör att du kan utföra övningen korrekt. Fördelar: För att intensifiera din Pilatespraktik. Perfekt för att träna ben, överarmar, bål, bröst och ryggmuskler. Plasthandtag för ett fast, halkfritt grepp. Pilatesringen är perfekt för att träna ben, överarmar, bål, bröst och ryggmuskler. Med det extra motståndet kommer du att intensifiera vanliga Pilatesövningar och använda de muskler du skulle träna utan ringen. Plasthandtag säkerställer ett fast grepp, även när du svettas. "Må bättre varje dag" - det är Tuntur's motto. Våra rötter går tillbaka till 1922, då två bröder grundade en cykelbutik i Finland. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Vårt produktsortiment utökas och förbättras ständigt, och vi erbjuder kvalitetsprodukter och utmärkta garantier. Specifikationer: Mått. Vikt: 310 gr. Material: plast, metall och skum. Färg: svart. Märke Tunturi, typ Stretchband, variant Default Title, SKU 14TUSYO066''',
 titel="Pilatesring Tunturi med plasthandtag, svart",
 seo_title="Pilatesring Tunturi, svart",
 meta="Tunturi Pilates Ring är en pilatesring i plast, metall och skum som ger motstånd under övningarna. Plasthandtag, vikt 310 g, färg svart.",
 intro="Tunturi Pilates Ring är en pilatesring som ger motstånd under pilatesövningarna. Ringen har plasthandtag.",
 passar=["Dig som vill ha extra motstånd i vanliga pilatesövningar","Dig som vill träna ben, överarmar, bål, bröst och ryggmuskler med en ring","Dig som vill ha handtag i plast"],
 spec=["Material: plast, metall och skum","Vikt: 310 g","Färg: svart","Plasthandtag"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Utelämnat: 'perfekt', effektlöften (utveckla muskelstyrka och uthållighet, träna djupa muskler utan specialutrustning, träna balans), 'fast, halkfritt grepp även när du svettas' som löfte, och Tunturis märkestext.",
 att_bekrafta=["Mått saknas (tom rad 'Mått.').","Produkten har taggen 'På beställning' men produkttypen är 'Stretchband', vilket verkar fel för en pilatesring.","Om handtagen är halkfria framgår bara som säljtext; utelämnat."])

