add(nr=215, id="10411932647690", orig_titel="Våg TUNTURI SC30 Smart Scale med app, vit",
 fakta='''Våg TUNTURI SC30 Smart Scale med app, vit. Tunturi SC30 vågen är mer än bara en viktenhet. Den har en rad funktioner som hjälper dig att få en överblick över din hälsa. Med sin eleganta design är denna våg ett oumbärligt verktyg för alla som vill förbättra sin hälsa. Vågen kan anslutas till din telefon via den kostnadsfria Fitdays-appen. Tunturi SC30 Smart Scale mäter: vikt, kroppsmasseindex (BMI), fettprocent, muskelmassa, fettfri massa, subkutant fett, intraabdominellt fett, kroppsvätskor, skelettmuskelvikt, kroppsålder, protein, BMR, benvikt, muskelprocent. Tillverkaren är: Tunturi. Detaljer: Mått: 26 x 26 x 1,8 cm. Vikt: 1 kg. Strömkälla: 2 x AAA-batterier (ingår). Maximal belastningsvikt: 180 kg. Märke Tunturi, typ Konditionsträning & Fitness, variant Default Title, SKU 14TUSSP002''',
 titel="Våg Tunturi SC30 med Fitdays-app, vit",
 seo_title="Våg Tunturi SC30 med Fitdays-app",
 meta="Tunturi SC30 är en våg som ansluts till telefonen via Fitdays-appen och mäter bland annat vikt, BMI och fettprocent. 26 x 26 x 1,8 cm, 2 x AAA ingår.",
 intro="Tunturi SC30 är en våg som kan anslutas till telefonen via Fitdays-appen. Den mäter bland annat vikt, BMI, fettprocent och muskelmassa.",
 passar=["Dig som vill koppla vågen till telefonen via Fitdays-appen","Dig som vill mäta vikt, BMI, fettprocent och muskelmassa","Användare upp till 180 kg"],
 spec=["Mäter: vikt, kroppsmasseindex (BMI), fettprocent, muskelmassa, fettfri massa, subkutant fett, intraabdominellt fett, kroppsvätskor, skelettmuskelvikt, kroppsålder, BMR, benvikt, muskelprocent","Mått: 26 x 26 x 1,8 cm","Vikt: 1 kg","Strömkälla: 2 x AAA-batterier (ingår)","Maximal belastningsvikt: 180 kg","Färg: vit (enligt titeln)"],
 faq=[("Hur ansluter jag vågen till telefonen?","Vågen kan anslutas till telefonen via Fitdays-appen.")], marke=None,
 motivering="Fakta ur källan. Utelämnat: 'mer än bara en viktenhet', 'överblick över din hälsa', 'oumbärligt verktyg', 'förbättra sin hälsa', 'elegant design', 'kostnadsfria' samt 'protein' i måttlistan (standarden förbjuder protein/hälsoord i texten).",
 att_bekrafta=["Måttlistan är lång och innehåller medicinskt klingande värden; det framgår inte hur noggranna mätningarna är. Inga noggrannhetspåståenden gjorda.","Proteinvärdet finns i källans måttlista men är medvetet utelämnat.","Vilka telefonsystem Fitdays-appen stöder framgår inte.","Färgen vit står bara i titeln."])
